scwin.vScrenID = "ULDSTF05971.xml";
scwin.vScrenTpCD = "";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo;
scwin.vListProcsStatCd;
scwin.vAcptNo;
scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.TR_JOB;
scwin.vSECT_CHG_TP_CD = "";
scwin.type = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_searchCode = function() {
    /*
    00726 - 소속부유형코드
    01361 - 소속부변경구분코드
    01362 - 벤처유형코드
    */
    var arrCid = [{
        cid: "SECT_TP_CD",
        cnm: "cmb_BFCHG_SECT_TP_CD"
    }, {
        cid: "SECT_TP_CD",
        cnm: "cmb_AFCHG_SECT_TP_CD"
    }, {
        cid: "SECT_CHG_TP_CD",
        cnm: "cmb_SECT_CHG_TP_CD"
    }, {
        cid: "SECT_INVSTG_TP_CD",
        cnm: "cmb_AFCHG_SECT_INVSTG_TP_CD"
    }, {
        cid: "SECT_CHG_RSN_CD",
        cnm: "cmb_SECT_CHG_RSN"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='SECT_TP_CD','SECT_TP_CD','SECT_CHG_TP_CD','SECT_INVSTG_TP_CD','SECT_CHG_RSN_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        //alert('[objCod]'+objCod);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                if (arrCid[i].cid == "VENT_TP_CD") {
                    if (dts_Cod.getCellData(j, "VALUE") == "10") {
                        strCbd = strCbd + "^-----------------------------------------------------";
                    }
                }
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_CheckForm = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[회사코드] 항목값이  없습니다.");
        txb_ISUR_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_SECT_CHG_TP_CD) == "") {
        $c.win.alert("[소속부변경구분]을 선택하세요.");
        cmb_SECT_CHG_TP_CD.focus();
        return false;
    }
    if (scwin.vSECT_CHG_TP_CD == 'N') {
        if (scwin.vSECT_CHG_TP_CD != $c.stf.getObjectValue(cmb_SECT_CHG_TP_CD)) {
            $c.win.alert("[소속부변경구분]값이 '신규상장'이면 [소속부변경구분]항목을 변경할 수 없습니다.");
            cmb_SECT_CHG_TP_CD.focus();
            return false;
            //심사팀에서 신규상장시 입력한 자료라서 수정 불가.
        }
    }
    if ($c.stf.getObjectValue(cmb_SECT_CHG_TP_CD) == "") {
        $c.win.alert("[소속부변경구분]을 선택하세요.");
        cmb_SECT_CHG_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_SECT_CHG_TP_CD) != "N") {
        //신규상장
        if ($c.stf.getObjectValue(cmb_BFCHG_SECT_TP_CD) == "") {
            $c.win.alert("[변경전 소속부] 항목값이  없습니다.");
            cmb_BFCHG_SECT_TP_CD.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(cmb_AFCHG_SECT_TP_CD) == "") {
        $c.win.alert("[변경후 소속부]를 선택하세요.");
        cmb_AFCHG_SECT_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_CHG_DD) == "") {
        $c.win.alert("[변경일]을 입력하세요.");
        edt_CHG_DD.focus();
        return false;
    }
    if (vCurDate >= $c.stf.getObjectValue(edt_CHG_DD)) {
        $c.win.alert("[변경일]을 현재일이후로 입력하세요.");
        edt_CHG_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_SECT_STRT_DD) == "") {
        if ($c.stf.getObjectValue(edt_SECT_END_DD) != "") {
            $c.win.alert("[소속부유효시작일]을 입력하세요.");
            edt_SECT_STRT_DD.focus();
            return false;
        }
    } else {
        if ($c.stf.getObjectValue(edt_SECT_END_DD) == "") {
            $c.win.alert("[소속부유효종료일]을 입력하세요.");
            edt_SECT_END_DD.focus();
            return false;
        }
        if (parseInt($c.stf.getObjectValue(edt_SECT_STRT_DD), 10) > parseInt($c.stf.getObjectValue(edt_SECT_END_DD), 10)) {
            $c.win.alert("[소속부유효종료일]은 [소속부유효시작일]보다 작아야 합니다. 다시 입력해주세요");
            return false;
        }
    }
    if ($c.stf.getObjectValue(cmb_AFCHG_SECT_INVSTG_TP_CD) == "") {
        $c.win.alert("[소속부 심사구분]를 선택하세요.");
        cmb_AFCHG_SECT_INVSTG_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_BFCHG_SECT_TP_CD) == "4") {
        //기술성장기업부
        if ($c.stf.getObjectValue(cmb_AFCHG_SECT_TP_CD) == "2" || $c.stf.getObjectValue(cmb_AFCHG_SECT_TP_CD) == "3") {
            $c.win.alert("변경전 소속부가 기술성장기업부일 경우 우량기업부로 변경만 가능합니다.");
            cmb_AFCHG_SECT_TP_CD.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(cmb_BFCHG_SECT_TP_CD) == "2" || //벤처 
        $c.stf.getObjectValue(cmb_BFCHG_SECT_TP_CD) == "3") {
        //중견
        if ($c.stf.getObjectValue(cmb_AFCHG_SECT_TP_CD) == "4") {
            $c.win.alert("변경전 소속부가 벤처나 중견일 경우 우량기업부로 변경만 가능합니다.");
            cmb_AFCHG_SECT_TP_CD.focus();
            return false;
        }
    }
    return true;
};
scwin.fn_duplicate_check = function() {
    var url = "/SectionTypeChange.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=checkDuplicate&inputMessageId=SECT_TYP_CHG_INOUT";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    url += "&CHG_DD=" + $c.stf.getObjectValue(edt_CHG_DD);
    dts_DUP_CHK.DataID = encodeURI(url);
    dts_DUP_CHK.Reset();
    //alert("fn_duplicate_check:"+dts_DUP_CHK.NameValue(1, "DUP_CHK"));
    return dts_DUP_CHK.getCellData(1, "DUP_CHK");
};
scwin.fn_save = function() {
    scwin.TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        if (scwin.fn_duplicate_check() == 'Y') {
            $c.win.alert("[변경일]이 동일한 일자로 이미  입력되었습니다.");
            return;
        }
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.fn_trs(TR_JOB_INSERT);
    }
};
scwin.fn_BfSectInvstgTpCd = function() {
    var url = "/listingCommon.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral&outputMessageId=SECT_TYP_CHG_INVSTG_INOUT";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=lds.stf.lstproc.scttypchg.bfchgsectinvstgtpcd.select";
    url += "&{P}param01=" + $c.stf.getObjectValue(txb_ISUR_CD);
    dts_bfSectInvstg.DataID = encodeURI(url);
    dts_bfSectInvstg.Reset();
};
scwin.fn_trs = function(jobType) {
    //소속부 변경전 심사코드 
    scwin.fn_BfSectInvstgTpCd();
    dts_Item.setCellData(1, "JOB_TYPE", jobType);
    dts_Item.setCellData(1, "ISUR_CD", $c.stf.getObjectValue(txb_ISUR_CD));
    dts_Item.setCellData(1, "LIST_BZ_TP_CD", LIST_BZ_TP_CD_234);
    dts_Item.setCellData(1, "SPOT_ISU_TRD_MKT_TP_CD", scwin.vSPOT_ISU_TRD_MKT_TP_CD);
    dts_Item.setCellData(1, "BFCHG_SECT_INVSTG_TP_CD", dts_bfSectInvstg.getCellData(1, "AFCHG_SECT_INVSTG_TP_CD"));
    scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    trs_Save.Action = "/SectionTypeChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=saveSectChgSimulationAction";
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Item)";
    trs_Save.Post();
};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};
scwin.dts_Item_OnLoadError = function() {
    $c.stf.alert_error(dts_Item);
};
scwin.dts_Item_OnLoadCompleted = function(rowcount) {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    scwin.vSECT_CHG_TP_CD = dts_Item.getCellData(1, "SECT_CHG_TP_CD");
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
};
scwin.trs_Save_OnSuccess = async function() {
    $c.lc.fn_alertMsg('S');
    //fn_parentRefresh();
    await $c.frame.CloseFrame();
};
scwin.img_SECT_STRT_DD_onclick = function() {
    popUpCalendar2(edt_SECT_STRT_DD);
};
scwin.img_SECT_END_DD_onclick = function() {
    popUpCalendar2(edt_SECT_END_DD);
};
scwin.img_CHG_DD_onclick = function() {
    popUpCalendar2(edt_CHG_DD);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Item);
    scwin.vSPOT_ISU_TRD_MKT_TP_CD = '2';
    dts_Item.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=SECT_TYP_CHG_INOUT";
    dts_Item.reset();
    dts_Item.insertRow();
    scwin.fn_searchCode();
    var parentWin = $c.frame.path("../");
    var dstOjb = parentWin.dts_List_1;
    var row = dstOjb.getFocusedRowIndex();
    $c.stf.setObjectValue(txb_ISUR_CD, dstOjb.getCellData(row, "ISUR_CD"));
    $c.stf.setObjectValue(txb_COM_NM, dstOjb.getCellData(row, "ISUR_NM"));
    $c.stf.setObjectValue(cmb_BFCHG_SECT_TP_CD, dstOjb.getCellData(row, "SECT_TP_CD")); //변경전 소속부 : 원부 소속부코드
    $c.stf.setObjectValue(cmb_AFCHG_SECT_TP_CD, dstOjb.getCellData(row, "NONSCHE_CD")); //변경후 소속부 : 수시 소속부결과코드
    $c.stf.setObjectValue(cmb_SECT_CHG_TP_CD, "M"); //변경구분 : 변경
    $c.stf.setObjectValue(cmb_AFCHG_SECT_INVSTG_TP_CD, "B"); //소속부심사구분:수시

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장

};
